//! OUTPUT current text and native default-value override state.
use super::*;
fn fixture()->(Document,Forms,Page){fixture_content("<span>before</span>tail")}
fn fixture_content(content:&str)->(Document,Forms,Page){let mut d=crate::html::parse(&format!("<html><body><form id=owner><label id=label for=output>Result</label><output id=output for=seed name=result>{content}</output><input id=field value=seed></form><div id=mount></div></body></html>"));d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://output-value.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn output_value_default_canonical_domstring_accessors_and_genuine_brands(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output');for(var property of ['value','defaultValue']){var descriptor=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,property);if(!descriptor||typeof descriptor.get!=='function'||typeof descriptor.set!=='function'||!descriptor.enumerable||!descriptor.configurable||descriptor.get.name!=='get '+property||descriptor.get.length!==0||descriptor.set.name!=='set '+property||descriptor.set.length!==1||Object.hasOwn(output,property)||descriptor.get.call(output)!=='beforetail')throw 'canonical output '+property;for(var bad of [{},Object.create(HTMLOutputElement.prototype),document.getElementById('field'),document.createElementNS('urn:foreign','output')]){var caught=false,calls=0;try{descriptor.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine output getter';caught=false;try{descriptor.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before native value conversion';}}"#);}
#[test]
fn output_value_default_native_modes_keep_text_identity_and_actual_child_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),old=output.firstChild,labels=output.labels,tokens=output.htmlFor,owner=output.form,watch=new MutationObserver(function(){});watch.observe(output,{childList:true});output.defaultValue='initial default';var initial=output.firstChild,records=watch.takeRecords();if(output.value!=='initial default'||output.defaultValue!==output.value||old.parentNode!==null||records.length!==1||records[0].addedNodes[0]!==initial)throw 'default mode replaces actual children';output.value='A\ud800z';var current=output.firstChild;records=watch.takeRecords();if(output.value!=='A\ud800z'||output.defaultValue!=='initial default'||current.data!==output.value||initial.parentNode!==null||records.length!==1||records[0].removedNodes[0]!==initial||records[0].addedNodes[0]!==current)throw 'value captures native default';output.textContent='external';watch.takeRecords();output.defaultValue='B\udfffz';if(output.value!=='external'||output.defaultValue!=='B\udfffz'||watch.takeRecords().length)throw 'override-only default setter';output.value='again';watch.takeRecords();var same=output.firstChild;output.value='again';records=watch.takeRecords();if(output.defaultValue!=='B\udfffz'||same===output.firstChild||same.parentNode!==null||records.length!==1)throw 'same current value creates fresh text';output.defaultValue=null;output.value=undefined;if(output.defaultValue!=='null'||output.value!=='undefined'||output.labels!==labels||labels[0].control!==output||output.htmlFor!==tokens||tokens.value!=='seed'||output.form!==owner||output.name!=='result')throw 'DOMString conversion and independent native authority';"#);}
#[test]
fn output_value_default_inert_clone_fresh_state_and_adoption_preserve_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),output=owner.createElement('output');output.defaultValue='original';output.value='A\ud800z';var copy=output.cloneNode(true),target=document.implementation.createHTMLDocument('target');if(copy.value!=='A\ud800z'||copy.defaultValue!==copy.value||output.defaultValue!=='original'||copy.firstChild===output.firstChild)throw 'clone initializes independent default override';target.adoptNode(output);output.textContent='external';if(output.ownerDocument!==target||output.value!=='external'||output.defaultValue!=='original')throw 'adoption preserves actual override';copy.defaultValue='B\udfffz';if(copy.value!=='B\udfffz'||copy.defaultValue!==copy.value||output.defaultValue!=='original')throw 'clone starts in default mode';var empty=owner.createElement('output');empty.value='';empty.textContent='later';if(empty.value!=='later'||empty.defaultValue!=='')throw 'empty nonnull native override';"#);}

#[test]
fn output_value_default_conversion_reentry_abrupt_and_author_shadows(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),descriptor=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'value'),defaults=Object.getOwnPropertyDescriptor(HTMLOutputElement.prototype,'defaultValue'),calls=0;descriptor.set.call(output,{toString:function(){calls++;output.defaultValue='during';return 'after';}});if(calls!==1||output.value!=='after'||output.defaultValue!=='during')throw 'capture after conversion reentry';var marker={},caught;try{output.value={toString:function(){output.defaultValue='effect';throw marker;}};}catch(e){caught=e;}if(caught!==marker||output.defaultValue!=='effect'||output.value!=='after')throw 'conversion effects retained';caught=false;try{output.value=Symbol('bad');}catch(e){caught=e instanceof TypeError;}if(!caught||output.value!=='after')throw 'symbol refusal';Object.defineProperty(output,'value',{value:'author',writable:true,configurable:true});Object.defineProperty(output,'defaultValue',{value:'author default',writable:true,configurable:true});descriptor.set.call(output,'native');defaults.set.call(output,'native default');if(output.value!=='author'||output.defaultValue!=='author default'||descriptor.get.call(output)!=='native'||defaults.get.call(output)!=='native default')throw 'native access ignores author shadows';delete output.value;delete output.defaultValue;if(output.value!=='native'||output.defaultValue!=='native default')throw 'native descriptors restored';"#);}
#[test]
fn output_value_default_native_and_inert_limits_leave_children_and_override_atomic(){for inert in [false,true]{for overridden in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=document.implementation.createHTMLDocument('inert'),output=owner.createElement('output');output.textContent='beforetail';"}else{"var output=document.getElementById('output');"});if overridden{run(&mut d,&mut f,&mut p,"output.value='current';");}run(&mut d,&mut f,&mut p,"var old=output.firstChild,watch=new MutationObserver(function(){});watch.observe(output,{childList:true});");let Value::Host(object)=p.runtime.execute("output;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("output")};p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone(),p.state.output_defaults.len(),p.state.output_defaults.storage_bytes());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.output_value_set(object,if overridden{"defaultValue"}else{"value"},&Value::String("long replacement".into())).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{inert}/{overridden}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone(),p.state.output_defaults.len(),p.state.output_defaults.storage_bytes()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,if overridden{"if(output.firstChild!==old||output.value!=='current'||output.defaultValue!=='beforetail'||watch.takeRecords().length)throw 'atomic override update';output.defaultValue='recovered';if(output.value!=='current'||output.defaultValue!=='recovered'||watch.takeRecords().length)throw 'override recovery';"}else{"if(output.firstChild!==old||output.defaultValue!=='beforetail'||watch.takeRecords().length)throw 'atomic capture';output.defaultValue='recovered';if(output.value!=='recovered'||output.defaultValue!=='recovered'||watch.takeRecords().length!==1)throw 'default mode recovery';"});}}}}
#[test]
fn output_value_default_override_getter_limits_and_recovery(){for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{r#"var owner=document.implementation.createHTMLDocument('inert'),output=owner.createElement('output');output.textContent='A\ud800z';output.value='current';"#}else{r#"var output=document.getElementById('output');output.textContent='A\ud800z';output.value='current';"#});let Value::Host(object)=p.runtime.execute("output;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("output")};let state=(p.state.retained,p.state.dom_commits,p.state.output_defaults.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.output_value_get(object,"defaultValue").is_err());assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_defaults.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,r#"if(output.defaultValue!=='A\ud800z'||output.value!=='current')throw 'override getter recovery';"#);}}}
#[test]
fn output_value_default_failed_child_transaction_does_not_publish_native_default(){for content in ["<input value=seed>","<script type=application/json>saved</script>"]{let(mut d,mut f,mut p)=fixture_content(content);run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),old=output.firstChild,watch=new MutationObserver(function(){});watch.observe(output,{childList:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.output_defaults.len(),p.state.output_defaults.storage_bytes());p.begin_job();assert!(p.runtime.execute("output.value='blocked';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_defaults.len(),p.state.output_defaults.storage_bytes()),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(output.firstChild!==old||watch.takeRecords().length)throw 'failed child publication';var fresh=document.createElement('output');fresh.defaultValue='default';fresh.value='current';if(fresh.defaultValue!=='default'||fresh.value!=='current')throw 'fresh recovery';");}}
#[test]
fn output_value_default_node_limit_rolls_back_capture_but_empty_value_keeps_default(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),old=output.firstChild,watch=new MutationObserver(function(){});watch.observe(output,{childList:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.output_defaults.len(),p.state.output_defaults.storage_bytes());let limit=p.state.node_limit;p.state.node_limit=d.nodes.len();p.begin_job();assert!(p.runtime.execute("output.value='blocked';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err().contains("node limit"));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_defaults.len(),p.state.output_defaults.storage_bytes()),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length)throw 'failed node admission';output.value='';if(output.value!==''||output.defaultValue!=='beforetail'||old.parentNode!==null||output.childNodes.length||watch.takeRecords().length!==1)throw 'empty value capture without node';output.defaultValue='new default';if(output.value!==''||output.defaultValue!=='new default'||watch.takeRecords().length)throw 'empty nonnull override';");p.state.node_limit=limit;}

#[test]
fn output_value_default_saved_child_accessors_reject_origin_before_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLOutputElement.prototype,'value'),defaults=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLOutputElement.prototype,'defaultValue'),calls=0;descriptor.set.call(output,'saved');defaults.set.call(output,'saved default');");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.output_defaults.len());p.set_location(&crate::navigation::address("https://foreign-output-value.test/",&crate::navigation::Location::home()).unwrap());for source in ["descriptor.set.call(output,{toString:function(){calls++;return 'bad';}});","descriptor.get.call(output);","defaults.set.call(output,{toString:function(){calls++;return 'bad';}});","defaults.get.call(output);"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_defaults.len()),state);}p.set_location(&crate::navigation::address("https://output-value.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||output.value!=='saved'||output.defaultValue!=='saved default')throw 'origin before conversion';descriptor.set.call(output,'fresh');if(output.value!=='fresh'||output.defaultValue!=='saved default')throw 'saved accessor recovery';");}
#[test]
fn output_value_default_sparse_authority_growth_and_exact_empty_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var outputs=[];for(var i=0;i<9;i++){var output=document.createElement('output');output.value='';outputs.push(output);}for(var i=0;i<outputs.length;i++){outputs[i].textContent='external';if(outputs[i].defaultValue!==''||outputs[i].value!=='external')throw 'distinct empty override records';}");assert_eq!(p.state.output_defaults.len(),9);let retained=p.state.retained;let backing=p.state.output_defaults.storage_bytes();run(&mut d,&mut f,&mut p,"for(var output of outputs){output.defaultValue='';if(output.value!=='external'||output.defaultValue!=='')throw 'empty override replacement';}");assert_eq!(p.state.output_defaults.storage_bytes(),backing);assert_eq!(p.state.retained,retained);}
